//! # Time-of-Day Failover Routing Strategy
//!
//! Implements a maintenance-window-aware connector selection strategy.
//! During a configured window (e.g. 02:00–02:30 UTC), traffic is automatically
//! rerouted from the primary connector to a fallback connector **before** failures
//! occur, rather than relying on post-failure retry logic.
//!
//! ## Design
//!
//! - Pure, side-effect-free logic: `apply` takes injected time → fully deterministic tests.
//! - The primary connector is moved to the **end** of the list (not removed), preserving
//!   the existing retry pipeline for edge cases.
//! - Multiple overlapping windows are applied in order; each may reorder independently.
//! - Malformed window config is skipped with a warning; routing continues unchanged.
//!
//! ## Example log output
//!
//! ```json
//! {
//!   "payment_id": "pay_123",
//!   "strategy": "time_window_failover",
//!   "primary_connector": "stripe",
//!   "fallback_connector": "razorpay",
//!   "current_time_utc": "02:10 UTC",
//!   "maintenance_window_match": true,
//!   "selected_connector": "razorpay"
//! }
//! ```

use serde::{Deserialize, Serialize};

use crate::logger;

// ---------------------------------------------------------------------------
// Configuration types
// ---------------------------------------------------------------------------

/// Configuration for a single maintenance window entry.
///
/// Example TOML:
/// ```toml
/// [[maintenance_windows.windows]]
/// primary_connector  = "stripe"
/// fallback_connector = "razorpay"
/// window_start_utc   = "02:00"
/// window_end_utc     = "02:30"
/// enabled            = true
/// ```
#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct MaintenanceWindowEntry {
    /// Connector to avoid during the window (e.g. `"stripe"`).
    pub primary_connector: String,
    /// Connector to route to during the window (e.g. `"razorpay"`).
    pub fallback_connector: String,
    /// Window start in UTC, `"HH:MM"` format (e.g. `"02:00"`).
    pub window_start_utc: String,
    /// Window end in UTC, `"HH:MM"` format, exclusive (e.g. `"02:30"`).
    pub window_end_utc: String,
    /// Set to `false` to disable without removing the config entry.
    #[serde(default = "bool_true")]
    pub enabled: bool,
}

fn bool_true() -> bool {
    true
}

/// Top-level config block that holds zero or more maintenance window entries.
#[derive(Debug, Clone, Default, Deserialize, Serialize)]
pub struct MaintenanceWindowConfig {
    /// List of maintenance window entries.  Empty by default (feature is off).
    #[serde(default)]
    pub windows: Vec<MaintenanceWindowEntry>,
}

// ---------------------------------------------------------------------------
// Internal time helpers
// ---------------------------------------------------------------------------

/// Minutes elapsed since midnight (0–1439).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct MinutesSinceMidnight(u32);

impl MinutesSinceMidnight {
    /// Parse `"HH:MM"` → `Some(MinutesSinceMidnight)`.
    /// Returns `None` on any parsing error or out-of-range value.
    fn from_hhmm(s: &str) -> Option<Self> {
        let (hh, mm) = s.split_once(':')?;
        let hours: u32 = hh.parse().ok()?;
        let minutes: u32 = mm.parse().ok()?;
        if hours > 23 || minutes > 59 {
            return None;
        }
        Some(Self(hours * 60 + minutes))
    }
}

/// Returns `true` when `now` falls in `[start, end)`.
///
/// Handles midnight-crossing windows (e.g. 23:00–01:00) by checking
/// `now >= start || now < end` when `start > end`.
fn is_in_window(now: u32, start: u32, end: u32) -> bool {
    if start <= end {
        now >= start && now < end
    } else {
        // Window crosses midnight
        now >= start || now < end
    }
}

// ---------------------------------------------------------------------------
// Strategy
// ---------------------------------------------------------------------------

/// Structured record emitted to the log for every routing decision.
struct RoutingDecisionLog<'a> {
    payment_id: &'a str,
    primary_connector: &'a str,
    fallback_connector: &'a str,
    current_time_utc: &'a str,
    maintenance_window_match: bool,
    selected_connector: &'a str,
}

/// The time-of-day failover routing strategy.
///
/// Given a resolved connector list, reorders it so that during a maintenance
/// window the fallback connector is first.  The primary connector is pushed to
/// the end rather than dropped, so the existing retry pipeline can still use it
/// as a last resort.
pub struct TimeWindowFailoverStrategy<'a> {
    config: &'a MaintenanceWindowConfig,
}

impl<'a> TimeWindowFailoverStrategy<'a> {
    pub fn new(config: &'a MaintenanceWindowConfig) -> Self {
        Self { config }
    }

    /// Apply maintenance-window reordering to `connectors`.
    ///
    /// # Parameters
    /// - `connectors`       – Resolved connector list from static/dynamic routing.
    /// - `payment_id`       – Used in log output only; no routing logic depends on it.
    /// - `now_minutes_utc`  – Minutes since midnight UTC. **Injected for testability**;
    ///                        call [`current_utc_minutes`] in production code.
    /// - `now_hhmm`         – Human-readable UTC time string (e.g. `"02:10 UTC"`).
    pub fn apply(
        &self,
        mut connectors: Vec<api_models::routing::RoutableConnectorChoice>,
        payment_id: &str,
        now_minutes_utc: u32,
        now_hhmm: &str,
    ) -> Vec<api_models::routing::RoutableConnectorChoice> {
        for window in &self.config.windows {
            if !window.enabled {
                continue;
            }

            let (start, end) = match (
                MinutesSinceMidnight::from_hhmm(&window.window_start_utc),
                MinutesSinceMidnight::from_hhmm(&window.window_end_utc),
            ) {
                (Some(s), Some(e)) => (s.0, e.0),
                _ => {
                    logger::warn!(
                        payment_id = %payment_id,
                        window_start = %window.window_start_utc,
                        window_end   = %window.window_end_utc,
                        "maintenance_window_routing: malformed window config — skipping entry"
                    );
                    continue;
                }
            };

            let in_window = is_in_window(now_minutes_utc, start, end);

            let decision = RoutingDecisionLog {
                payment_id,
                primary_connector: &window.primary_connector,
                fallback_connector: &window.fallback_connector,
                current_time_utc: now_hhmm,
                maintenance_window_match: in_window,
                selected_connector: if in_window {
                    &window.fallback_connector
                } else {
                    &window.primary_connector
                },
            };

            logger::info!(
                payment_id                = %decision.payment_id,
                strategy                  = "time_window_failover",
                primary_connector         = %decision.primary_connector,
                fallback_connector        = %decision.fallback_connector,
                current_time_utc          = %decision.current_time_utc,
                maintenance_window_match  = %decision.maintenance_window_match,
                selected_connector        = %decision.selected_connector,
                "maintenance_window_routing: routing decision"
            );

            if in_window {
                connectors = reorder_for_failover(
                    connectors,
                    &window.primary_connector,
                    &window.fallback_connector,
                );
            }
        }

        connectors
    }
}

/// Move `fallback` connector(s) to the front; push `primary` connector(s) to
/// the end.  All other connectors are preserved in their original order.
///
/// This guarantees:
/// 1. Fallback is tried first during maintenance.
/// 2. Primary remains available as a retry target.
fn reorder_for_failover(
    connectors: Vec<api_models::routing::RoutableConnectorChoice>,
    primary: &str,
    fallback: &str,
) -> Vec<api_models::routing::RoutableConnectorChoice> {
    let mut fallbacks = Vec::new();
    let mut others = Vec::new();
    let mut primaries = Vec::new();

    for c in connectors {
        let name = c.connector.to_string();
        if name == fallback {
            fallbacks.push(c);
        } else if name == primary {
            primaries.push(c);
        } else {
            others.push(c);
        }
    }

    // Order: fallback → others → primary (for retry)
    fallbacks.extend(others);
    fallbacks.extend(primaries);
    fallbacks
}

// ---------------------------------------------------------------------------
// Clock helper (production use)
// ---------------------------------------------------------------------------

/// Return `(minutes_since_midnight_utc, "HH:MM UTC")` using the `time` crate.
///
/// Kept separate from `apply` so tests can inject a deterministic time.
pub fn current_utc_time() -> (u32, String) {
    let now = time::OffsetDateTime::now_utc();
    let minutes = now.hour() as u32 * 60 + now.minute() as u32;
    let hhmm = format!("{:02}:{:02} UTC", now.hour(), now.minute());
    (minutes, hhmm)
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use api_models::routing::{RoutableChoiceKind, RoutableConnectorChoice};
    use euclid::enums::RoutableConnectors;

    use super::*;

    // -- helpers -------------------------------------------------------------

    fn make_connector(c: RoutableConnectors) -> RoutableConnectorChoice {
        RoutableConnectorChoice {
            choice_kind: RoutableChoiceKind::OnlyConnector,
            connector: c,
            merchant_connector_id: None,
        }
    }

    fn stripe() -> RoutableConnectorChoice {
        make_connector(RoutableConnectors::Stripe)
    }
    fn razorpay() -> RoutableConnectorChoice {
        make_connector(RoutableConnectors::Razorpay)
    }
    fn adyen() -> RoutableConnectorChoice {
        make_connector(RoutableConnectors::Adyen)
    }

    fn stripe_razorpay_window() -> MaintenanceWindowConfig {
        MaintenanceWindowConfig {
            windows: vec![MaintenanceWindowEntry {
                primary_connector: "stripe".into(),
                fallback_connector: "razorpay".into(),
                window_start_utc: "02:00".into(),
                window_end_utc: "02:30".into(),
                enabled: true,
            }],
        }
    }

    fn apply(
        config: &MaintenanceWindowConfig,
        connectors: Vec<RoutableConnectorChoice>,
        now_minutes: u32,
    ) -> Vec<RoutableConnectorChoice> {
        TimeWindowFailoverStrategy::new(config).apply(
            connectors,
            "pay_test",
            now_minutes,
            "HH:MM UTC",
        )
    }

    // -- Happy path ----------------------------------------------------------

    /// Outside the maintenance window: primary connector must be first.
    #[test]
    fn outside_window_primary_is_first() {
        let result = apply(&stripe_razorpay_window(), vec![stripe(), razorpay()], 60); // 01:00
        assert_eq!(result[0].connector, RoutableConnectors::Stripe);
    }

    /// Inside the maintenance window: fallback connector must be first.
    #[test]
    fn inside_window_fallback_is_first() {
        let result = apply(&stripe_razorpay_window(), vec![stripe(), razorpay()], 130); // 02:10
        assert_eq!(result[0].connector, RoutableConnectors::Razorpay);
    }

    /// Primary connector must still be present in the list for retry.
    #[test]
    fn inside_window_primary_preserved_for_retry() {
        let result = apply(&stripe_razorpay_window(), vec![stripe(), razorpay()], 130);
        assert!(
            result.iter().any(|c| c.connector == RoutableConnectors::Stripe),
            "primary connector must remain in retry list"
        );
    }

    // -- Boundary tests ------------------------------------------------------

    /// At exactly the start of the window (inclusive): failover active.
    #[test]
    fn at_window_start_boundary_failover_active() {
        let result = apply(&stripe_razorpay_window(), vec![stripe(), razorpay()], 120); // 02:00
        assert_eq!(result[0].connector, RoutableConnectors::Razorpay);
    }

    /// One minute before the end of the window: failover still active.
    #[test]
    fn one_minute_before_end_failover_active() {
        let result = apply(&stripe_razorpay_window(), vec![stripe(), razorpay()], 149); // 02:29
        assert_eq!(result[0].connector, RoutableConnectors::Razorpay);
    }

    /// At exactly the end of the window (exclusive): failover NOT active.
    #[test]
    fn at_window_end_boundary_failover_inactive() {
        let result = apply(&stripe_razorpay_window(), vec![stripe(), razorpay()], 150); // 02:30
        assert_eq!(result[0].connector, RoutableConnectors::Stripe);
    }

    // -- Multi-connector ordering --------------------------------------------

    /// With three connectors, inside window the order should be:
    /// razorpay → adyen → stripe.
    #[test]
    fn multi_connector_order_inside_window() {
        let result = apply(
            &stripe_razorpay_window(),
            vec![stripe(), adyen(), razorpay()],
            130,
        );
        assert_eq!(result[0].connector, RoutableConnectors::Razorpay);
        assert_eq!(result[1].connector, RoutableConnectors::Adyen);
        assert_eq!(result[2].connector, RoutableConnectors::Stripe);
    }

    // -- Failure / edge cases ------------------------------------------------

    /// When the fallback connector is absent from the routing list and we are
    /// in the window, the primary is still pushed to the end.
    #[test]
    fn fallback_not_in_list_primary_demoted() {
        let result = apply(&stripe_razorpay_window(), vec![stripe(), adyen()], 130);
        assert_eq!(
            result.last().unwrap().connector,
            RoutableConnectors::Stripe,
            "primary must be last when fallback is absent"
        );
    }

    /// Malformed `window_start_utc` / `window_end_utc` → window is skipped,
    /// connector list returned unchanged.
    #[test]
    fn malformed_time_window_skipped() {
        let config = MaintenanceWindowConfig {
            windows: vec![MaintenanceWindowEntry {
                primary_connector: "stripe".into(),
                fallback_connector: "razorpay".into(),
                window_start_utc: "not-a-time".into(),
                window_end_utc: "also-bad".into(),
                enabled: true,
            }],
        };
        let result = apply(&config, vec![stripe(), razorpay()], 130);
        // List must be unchanged since window was skipped
        assert_eq!(result[0].connector, RoutableConnectors::Stripe);
    }

    /// `enabled = false` → window is skipped even if time matches.
    #[test]
    fn disabled_window_no_reorder() {
        let config = MaintenanceWindowConfig {
            windows: vec![MaintenanceWindowEntry {
                primary_connector: "stripe".into(),
                fallback_connector: "razorpay".into(),
                window_start_utc: "02:00".into(),
                window_end_utc: "02:30".into(),
                enabled: false,
            }],
        };
        let result = apply(&config, vec![stripe(), razorpay()], 130);
        assert_eq!(result[0].connector, RoutableConnectors::Stripe);
    }

    /// Empty window config → list returned unchanged.
    #[test]
    fn empty_config_no_change() {
        let config = MaintenanceWindowConfig::default();
        let result = apply(&config, vec![stripe(), razorpay()], 130);
        assert_eq!(result[0].connector, RoutableConnectors::Stripe);
    }

    // -- Midnight-crossing window --------------------------------------------

    /// Window that spans midnight (23:00–01:00).
    #[test]
    fn midnight_crossing_window_before_midnight() {
        let config = MaintenanceWindowConfig {
            windows: vec![MaintenanceWindowEntry {
                primary_connector: "stripe".into(),
                fallback_connector: "razorpay".into(),
                window_start_utc: "23:00".into(),
                window_end_utc: "01:00".into(),
                enabled: true,
            }],
        };
        // 23:30 → inside window
        let result = apply(&config, vec![stripe(), razorpay()], 23 * 60 + 30);
        assert_eq!(result[0].connector, RoutableConnectors::Razorpay);
    }

    #[test]
    fn midnight_crossing_window_after_midnight() {
        let config = MaintenanceWindowConfig {
            windows: vec![MaintenanceWindowEntry {
                primary_connector: "stripe".into(),
                fallback_connector: "razorpay".into(),
                window_start_utc: "23:00".into(),
                window_end_utc: "01:00".into(),
                enabled: true,
            }],
        };
        // 00:30 → inside window
        let result = apply(&config, vec![stripe(), razorpay()], 30);
        assert_eq!(result[0].connector, RoutableConnectors::Razorpay);
    }

    #[test]
    fn midnight_crossing_window_at_end_boundary() {
        let config = MaintenanceWindowConfig {
            windows: vec![MaintenanceWindowEntry {
                primary_connector: "stripe".into(),
                fallback_connector: "razorpay".into(),
                window_start_utc: "23:00".into(),
                window_end_utc: "01:00".into(),
                enabled: true,
            }],
        };
        // 01:00 → exclusive end, outside window
        let result = apply(&config, vec![stripe(), razorpay()], 60);
        assert_eq!(result[0].connector, RoutableConnectors::Stripe);
    }

    // -- Pure unit tests on helpers ------------------------------------------

    #[test]
    fn is_in_window_normal_range() {
        assert!(is_in_window(130, 120, 150)); // 02:10 inside 02:00–02:30
        assert!(!is_in_window(119, 120, 150)); // 01:59 before start
        assert!(!is_in_window(150, 120, 150)); // 02:30 at exclusive end
    }

    #[test]
    fn is_in_window_midnight_crossing() {
        assert!(is_in_window(23 * 60 + 30, 23 * 60, 60)); // 23:30 inside 23:00–01:00
        assert!(is_in_window(30, 23 * 60, 60)); // 00:30 inside 23:00–01:00
        assert!(!is_in_window(60, 23 * 60, 60)); // 01:00 at exclusive end
    }

    #[test]
    fn minutes_from_hhmm_valid_values() {
        assert_eq!(
            MinutesSinceMidnight::from_hhmm("00:00"),
            Some(MinutesSinceMidnight(0))
        );
        assert_eq!(
            MinutesSinceMidnight::from_hhmm("02:30"),
            Some(MinutesSinceMidnight(150))
        );
        assert_eq!(
            MinutesSinceMidnight::from_hhmm("23:59"),
            Some(MinutesSinceMidnight(1439))
        );
    }

    #[test]
    fn minutes_from_hhmm_invalid_values() {
        assert_eq!(MinutesSinceMidnight::from_hhmm("24:00"), None); // hour out of range
        assert_eq!(MinutesSinceMidnight::from_hhmm("02:60"), None); // minute out of range
        assert_eq!(MinutesSinceMidnight::from_hhmm("bad"), None); // no colon
        assert_eq!(MinutesSinceMidnight::from_hhmm(""), None); // empty string
        assert_eq!(MinutesSinceMidnight::from_hhmm(":"), None); // no digits
    }
}

