pub async fn perform_eligibility_analysis_with_fallback(
    state: &SessionState,
    key_store: &domain::MerchantKeyStore,
    chosen: Vec<routing_types::RoutableConnectorChoice>,
    transaction_data: &routing::TransactionData<'_>,
    eligible_connectors: Option<Vec<api_enums::RoutableConnectors>>,
    business_profile: &domain::Profile,
) -> RoutingResult<Vec<routing_types::RoutableConnectorChoice>> {
    logger::debug!("euclid_routing: performing eligibility");

    #[cfg(feature = "v1")]
    let eligible_connectors =
        update_eligible_connectors_for_installments(state, transaction_data, eligible_connectors);

    let mut final_selection = perform_eligibility_analysis(
        state,
        key_store,
        chosen,
        transaction_data,
        eligible_connectors.as_ref(),
        business_profile.get_id(),
    )
    .await?;

    let fallback_selection = perform_fallback_routing(
        state,
        key_store,
        transaction_data,
        eligible_connectors.as_ref(),
        business_profile,
    )
    .await;

    final_selection.append(
        &mut fallback_selection
            .unwrap_or_default()
            .iter()
            .filter(|&routable_connector_choice| {
                !final_selection.contains(routable_connector_choice)
            })
            .cloned()
            .collect::<Vec<_>>(),
    );

    // -----------------------------------------------------------------------
    // Time-of-day failover: reorder connectors based on maintenance windows.
    // Applied after eligibility so we only reorder connectors that are valid
    // for this payment.  The primary connector is moved to the end (not
    // dropped) so the existing retry pipeline can still reach it.
    // -----------------------------------------------------------------------
    let payment_id = match transaction_data {
        routing::TransactionData::Payment(pd) => {
            pd.payment_attempt.payment_id.get_string_repr().to_string()
        }
        #[cfg(feature = "payouts")]
        routing::TransactionData::Payout(pd) => {
            pd.payout_attempt.payout_id.get_string_repr().to_string()
        }
    };

    let (now_minutes, now_hhmm) =
        crate::core::payments::maintenance_window::current_utc_time();

    let mw_strategy = crate::core::payments::maintenance_window::TimeWindowFailoverStrategy::new(
        &state.conf.maintenance_windows,
    );

    final_selection = mw_strategy.apply(final_selection, &payment_id, now_minutes, &now_hhmm);
    // -----------------------------------------------------------------------

    let final_selected_connectors = final_selection
        .iter()
        .map(|item| item.connector)
        .collect::<Vec<_>>();
    logger::debug!(final_selected_connectors_for_routing=?final_selected_connectors, "euclid_routing: List of final selected connectors for routing");

    Ok(final_selection)
}

