 *
 * All connector names are lowercase snake_case matching Hyperswitch's
 * RoutableConnectors enum (e.g. "stripe", "razorpay", "adyen").
 */

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

export interface MaintenanceWindowEntry {
  /** Connector to avoid during the window (e.g. "stripe"). */
  primaryConnector: string;
  /** Connector to use during the window (e.g. "razorpay"). */
  fallbackConnector: string;
  /** Window start in UTC, "HH:MM" format, inclusive (e.g. "02:00"). */
  windowStartUtc: string;
  /** Window end in UTC, "HH:MM" format, exclusive (e.g. "02:30"). */
  windowEndUtc: string;
  /**
   * Set to false to temporarily disable without removing the entry.
   * Defaults to true.
   */
  enabled: boolean;
}

export interface MaintenanceWindowConfig {
  /** Zero or more maintenance window entries. Empty = feature off. */
  windows: MaintenanceWindowEntry[];
}

export interface AppConfig {
  port: number;
  maintenanceWindows: MaintenanceWindowConfig;
}

// ---------------------------------------------------------------------------
// Strategy I/O
// ---------------------------------------------------------------------------

/** A single routing decision for one maintenance window entry. */
export interface RoutingDecision {
  strategy: "time_window_failover";
  primaryConnector: string;
  fallbackConnector: string;
  currentTimeUtc: string;
  maintenanceWindowMatch: boolean;
  selectedConnector: string;
}

/** Full output from the failover strategy. */
export interface FailoverResult {
  paymentId: string;
  orderedConnectors: string[];
  /**
   * One entry per evaluated window.
   * Empty when no windows are configured or all are disabled.
   */
  decisions: RoutingDecision[];
}

// ---------------------------------------------------------------------------
// HTTP request / response shapes
// ---------------------------------------------------------------------------

export interface RouteRequest {
  paymentId: string;
  /** Ordered connector list from the upstream routing algorithm. */
  connectors: string[];
}

export interface RouteResponse {
  paymentId: string;
