/**
 * Configuration loader.
 *
 * Resolution order (later sources win):
 *   1. config/default.json   – checked-in defaults
 *   2. Environment variables – ROUTING_PORT, MAINTENANCE_WINDOWS_JSON
 *
 * MAINTENANCE_WINDOWS_JSON can be a JSON string of MaintenanceWindowConfig,
 * useful for container / k8s deployments without file mounts.
 */

import * as fs from "fs";
import * as path from "path";
import type { AppConfig, MaintenanceWindowConfig } from "../types";

const DEFAULT_CONFIG_PATH = path.resolve(
  __dirname,
  "../../config/default.json"
);

function loadDefaultFile(): Partial<AppConfig> {
  try {
    const raw = fs.readFileSync(DEFAULT_CONFIG_PATH, "utf8");
    return JSON.parse(raw) as Partial<AppConfig>;
  } catch {
    return {};
  }
}

function loadFromEnv(): Partial<AppConfig> {
  const result: Partial<AppConfig> = {};

  if (process.env["ROUTING_PORT"]) {
    const port = parseInt(process.env["ROUTING_PORT"], 10);
    if (!isNaN(port)) result.port = port;
  }

  if (process.env["MAINTENANCE_WINDOWS_JSON"]) {
    try {
      result.maintenanceWindows = JSON.parse(
        process.env["MAINTENANCE_WINDOWS_JSON"]
      ) as MaintenanceWindowConfig;
    } catch {
      console.warn(
        "[config] MAINTENANCE_WINDOWS_JSON is not valid JSON — ignoring"
      );
    }
  }

  return result;
}

const defaults: AppConfig = {
  port: 3000,
  maintenanceWindows: { windows: [] },
};

export function loadConfig(): AppConfig {
  const fileConfig = loadDefaultFile();
  const envConfig = loadFromEnv();
  return { ...defaults, ...fileConfig, ...envConfig };
}

