/**
 * # Time-of-Day Failover Routing Strategy
 *
 * During a configured maintenance window, traffic is proactively rerouted
 * from the primary connector to a fallback connector — before failures occur.
 *
 * ## Design principles
 *
 * - **Pure function**: `apply()` accepts injected time (`nowMinutesUtc`) so
 *   every test is deterministic with no mocking required.
 * - **Reorder, don't remove**: the primary connector is moved to the end of
 *   the list (not dropped), preserving the retry pipeline.
 * - **Fail open**: malformed config is skipped with a warning; routing is
 *   never blocked by a bad window entry.
 * - **Midnight crossing**: windows like "23:00"–"01:00" are handled correctly.
 *
 * ## Structured log output (per window, always)
 *
 * ```json
 * {
 *   "payment_id": "pay_123",
 *   "strategy": "time_window_failover",
 *   "primary_connector": "stripe",
 *   "fallback_connector": "razorpay",
 *   "current_time_utc": "02:10 UTC",
 *   "maintenance_window_match": true,
 *   "selected_connector": "razorpay"
 * }
 * ```
 */

import type {
  FailoverResult,
  MaintenanceWindowConfig,
  MaintenanceWindowEntry,
  RoutingDecision,
} from "../types";
import { logger } from "../logger";

// ---------------------------------------------------------------------------
// Time helpers
// ---------------------------------------------------------------------------

/**
 * Parse "HH:MM" → minutes since midnight.
 * Returns `null` on any parse error or out-of-range value.
 */
export function parseHHMM(s: string): number | null {
  const match = /^(\d{1,2}):(\d{2})$/.exec(s);
  if (!match) return null;

  const hours = parseInt(match[1]!, 10);
  const minutes = parseInt(match[2]!, 10);

  if (hours > 23 || minutes > 59) return null;
  return hours * 60 + minutes;
}

/**
 * Returns true when `nowMinutes` falls in `[startMinutes, endMinutes)`.
 *
 * Handles midnight-crossing windows (start > end) by checking
 * `now >= start || now < end`.
 */
export function isInWindow(
  nowMinutes: number,
  startMinutes: number,
  endMinutes: number
): boolean {
  if (startMinutes <= endMinutes) {
    return nowMinutes >= startMinutes && nowMinutes < endMinutes;
  }
  // Midnight-crossing window
  return nowMinutes >= startMinutes || nowMinutes < endMinutes;
}

/**
 * Returns current UTC time as `(minutesSinceMidnight, "HH:MM UTC")`.
 * Kept separate from `apply()` so tests can inject deterministic time.
 */
export function currentUtcTime(): { minutes: number; label: string } {
  const now = new Date();
  const hours = now.getUTCHours();
  const mins = now.getUTCMinutes();
  return {
    minutes: hours * 60 + mins,
    label: `${String(hours).padStart(2, "0")}:${String(mins).padStart(2, "0")} UTC`,
  };
}

// ---------------------------------------------------------------------------
// Reorder helper
// ---------------------------------------------------------------------------

/**
 * Move `fallback` connector(s) to the front; push `primary` connector(s) to
 * the end.  All other connectors are preserved in their original relative order.
 *
 * Result: [fallback(s), others..., primary(s)]
 */
export function reorderForFailover(
  connectors: string[],
  primary: string,
  fallback: string
): string[] {
  const fallbacks: string[] = [];
  const others: string[] = [];
  const primaries: string[] = [];

  for (const c of connectors) {
    if (c === fallback) fallbacks.push(c);
    else if (c === primary) primaries.push(c);
    else others.push(c);
  }

  return [...fallbacks, ...others, ...primaries];
}

// ---------------------------------------------------------------------------
// Strategy
// ---------------------------------------------------------------------------

export class TimeWindowFailoverStrategy {
  constructor(private readonly config: MaintenanceWindowConfig) {}

  /**
   * Apply maintenance-window reordering to a connector list.
   *
   * @param connectors     Resolved connector list from upstream routing.
   * @param paymentId      Used in log output only; no routing logic depends on it.
   * @param nowMinutesUtc  Minutes since midnight UTC. **Inject in tests** to keep
   *                       them deterministic.  Defaults to current UTC wall time.
   * @param nowLabel       Human-readable time label for logging (e.g. "02:10 UTC").
   *                       Inferred from `nowMinutesUtc` if not provided.
   */
  apply(
    connectors: string[],
    paymentId: string,
    nowMinutesUtc?: number,
    nowLabel?: string
  ): FailoverResult {
    const clock = currentUtcTime();
    const now = nowMinutesUtc ?? clock.minutes;
    const timeLabel =
      nowLabel ??
      (nowMinutesUtc !== undefined
        ? `${String(Math.floor(nowMinutesUtc / 60)).padStart(2, "0")}:${String(nowMinutesUtc % 60).padStart(2, "0")} UTC`
        : clock.label);

    let ordered = [...connectors];
    const decisions: RoutingDecision[] = [];

    for (const window of this.config.windows) {
      if (!window.enabled) continue;

      const start = parseHHMM(window.windowStartUtc);
      const end = parseHHMM(window.windowEndUtc);

      if (start === null || end === null) {
        logger.warn({
          paymentId,
          windowStart: window.windowStartUtc,
          windowEnd: window.windowEndUtc,
          msg: "maintenance_window_routing: malformed window config — skipping entry",
        });
        continue;
      }

      const inWindow = isInWindow(now, start, end);
      const selectedConnector = inWindow
        ? window.fallbackConnector
        : window.primaryConnector;

      const decision: RoutingDecision = {
        strategy: "time_window_failover",
        primaryConnector: window.primaryConnector,
        fallbackConnector: window.fallbackConnector,
        currentTimeUtc: timeLabel,
        maintenanceWindowMatch: inWindow,
        selectedConnector,
      };

      logger.info({
        payment_id: paymentId,
        strategy: decision.strategy,
        primary_connector: decision.primaryConnector,
        fallback_connector: decision.fallbackConnector,
        current_time_utc: decision.currentTimeUtc,
        maintenance_window_match: decision.maintenanceWindowMatch,
        selected_connector: decision.selectedConnector,
        msg: "maintenance_window_routing: routing decision",
      });

      decisions.push(decision);

      if (inWindow) {
        ordered = reorderForFailover(
          ordered,
          window.primaryConnector,
          window.fallbackConnector
        );
      }
    }

    return { paymentId, orderedConnectors: ordered, decisions };
  }
}

/**
 * Validate a single MaintenanceWindowEntry at startup.
 * Returns an array of validation error messages (empty = valid).
 */
export function validateWindowEntry(entry: MaintenanceWindowEntry): string[] {
  const errors: string[] = [];
  if (parseHHMM(entry.windowStartUtc) === null) {
    errors.push(
      `windowStartUtc "${entry.windowStartUtc}" is not a valid HH:MM time`
    );
  }
  if (parseHHMM(entry.windowEndUtc) === null) {
    errors.push(
      `windowEndUtc "${entry.windowEndUtc}" is not a valid HH:MM time`
    );
  }
  if (!entry.primaryConnector) {
    errors.push("primaryConnector must not be empty");
  }
  if (!entry.fallbackConnector) {
    errors.push("fallbackConnector must not be empty");
  }
  return errors;
}

/** Log config validation warnings at startup. Does not throw. */
export function warnOnInvalidConfig(config: MaintenanceWindowConfig): void {
  config.windows.forEach((w, i) => {
    const errs = validateWindowEntry(w);
    if (errs.length > 0) {
      logger.warn(
        {
          windowIndex: i,
          errors: errs,
          msg: `maintenance_window_routing: window[${i}] has invalid config`,
        },
        `maintenance_window_routing: window[${i}] has invalid config`
      );
    }
  });
}

