/**
 * POST /v1/route
 *
 * Accepts a payment ID and an ordered connector list from the upstream
 * routing algorithm.  Applies the maintenance-window failover strategy
 * and returns the reordered list along with structured routing decisions.
 *
 * Request body:
 * ```json
 * {
 *   "paymentId": "pay_123",
 *   "connectors": ["stripe", "razorpay", "adyen"]
 * }
 * ```
 *
 * Response:
 * ```json
 * {
 *   "paymentId": "pay_123",
 *   "orderedConnectors": ["razorpay", "adyen", "stripe"],
 *   "decisions": [{
 *     "strategy": "time_window_failover",
 *     "primaryConnector": "stripe",
 *     "fallbackConnector": "razorpay",
 *     "currentTimeUtc": "02:10 UTC",
 *     "maintenanceWindowMatch": true,
 *     "selectedConnector": "razorpay"
 *   }],
 *   "routedAt": "2026-05-22T02:10:00.000Z"
 * }
 * ```
 */

import { Router, Request, Response } from "express";
import { TimeWindowFailoverStrategy } from "../strategy/maintenance-window";
import type { AppConfig, RouteRequest, RouteResponse } from "../types";
import { logger } from "../logger";

export function createRouteRouter(config: AppConfig): Router {
  const router = Router();
  const strategy = new TimeWindowFailoverStrategy(config.maintenanceWindows);

  router.post("/v1/route", (req: Request, res: Response) => {
    const body = req.body as Partial<RouteRequest>;

    // Input validation
    if (typeof body.paymentId !== "string" || !body.paymentId.trim()) {
      res
        .status(400)
        .json({ error: "paymentId is required and must be a non-empty string" });
      return;
    }

    if (
      !Array.isArray(body.connectors) ||
      body.connectors.length === 0 ||
      !body.connectors.every((c) => typeof c === "string")
    ) {
      res.status(400).json({
        error: "connectors is required and must be a non-empty array of strings",
      });
      return;
    }

    const paymentId = body.paymentId.trim();
    const connectors: string[] = body.connectors;

    logger.info(
      {
        paymentId,
        inputConnectors: connectors,
        msg: "routing_service: received routing request",
      },
      "routing_service: received routing request"
    );

    const result = strategy.apply(connectors, paymentId);

    const response: RouteResponse = {
      paymentId: result.paymentId,
      orderedConnectors: result.orderedConnectors,
      decisions: result.decisions,
      routedAt: new Date().toISOString(),
    };

    res.status(200).json(response);
  });

  return router;
}

/**
 * Express application factory.
 *
 * Kept separate from index.ts so integration tests can construct
 * the app without binding to a real port.
 */

import express from "express";
import { healthRouter } from "./routes/health";
import { createRouteRouter } from "./routes/route";
import type { AppConfig } from "./types";
import { logger } from "./logger";
import { warnOnInvalidConfig } from "./strategy/maintenance-window";

export function createApp(config: AppConfig): express.Application {
  const app = express();

  app.use(express.json());

  // Request logging middleware
  app.use((req, _res, next) => {
    logger.info(
      { method: req.method, path: req.path, msg: "incoming request" },
      "incoming request"
    );
    next();
  });

  // Warn on any invalid maintenance window entries at startup (fail open)
  warnOnInvalidConfig(config.maintenanceWindows);

  // Routes
  app.use("/", healthRouter);
  app.use("/", createRouteRouter(config));

  // 404 handler
  app.use((_req, res) => {
    res.status(404).json({ error: "not found" });
  });

  // Error handler
  app.use(
    (
      err: Error,
      _req: express.Request,
      res: express.Response,
      _next: express.NextFunction
    ) => {
      logger.error({ err, msg: "unhandled error" }, "unhandled error");
      res.status(500).json({ error: "internal server error" });
    }
  );

  return app;
}

