    expect(parseHHMM("not-a-time")).toBeNull();
  });
});

// ---------------------------------------------------------------------------
// isInWindow
// ---------------------------------------------------------------------------

describe("isInWindow", () => {
  describe("non-crossing windows (start <= end)", () => {
    it("returns true when now is inside the window", () => {
      expect(isInWindow(130, 120, 150)).toBe(true); // 02:10 inside 02:00–02:30
    });

    it("returns true at the inclusive start", () => {
      expect(isInWindow(120, 120, 150)).toBe(true); // 02:00 exactly
    });

    it("returns false at the exclusive end", () => {
      expect(isInWindow(150, 120, 150)).toBe(false); // 02:30 exactly
    });

    it("returns false before the window starts", () => {
      expect(isInWindow(119, 120, 150)).toBe(false); // 01:59
    });

    it("returns false after the window ends", () => {
      expect(isInWindow(151, 120, 150)).toBe(false); // 02:31
    });
  });

  describe("midnight-crossing windows (start > end)", () => {
    // Window: 23:00–01:00
    const start = 23 * 60; // 1380
    const end = 60; // 01:00

    it("returns true at 23:30 (before midnight, inside window)", () => {
      expect(isInWindow(23 * 60 + 30, start, end)).toBe(true);
    });

    it("returns true at 00:30 (after midnight, inside window)", () => {
      expect(isInWindow(30, start, end)).toBe(true);
    });

    it("returns false at 01:00 (exclusive end)", () => {
      expect(isInWindow(60, start, end)).toBe(false);
    });

    it("returns false at 12:00 (midday, outside window)", () => {
      expect(isInWindow(12 * 60, start, end)).toBe(false);
    });
  });
});

