    ]);
  });

  it("preserves other connectors in the middle", () => {
    expect(
      reorderForFailover([STRIPE, ADYEN, RAZORPAY], STRIPE, RAZORPAY)
    ).toEqual([RAZORPAY, ADYEN, STRIPE]);
  });

  it("returns only others when fallback absent", () => {
    expect(reorderForFailover([STRIPE, ADYEN], STRIPE, RAZORPAY)).toEqual([
      ADYEN,
      STRIPE,
    ]);
  });

  it("handles single connector (primary only)", () => {
    expect(reorderForFailover([STRIPE], STRIPE, RAZORPAY)).toEqual([STRIPE]);
  });

  it("handles empty list", () => {
    expect(reorderForFailover([], STRIPE, RAZORPAY)).toEqual([]);
  });
});

// ---------------------------------------------------------------------------
// TimeWindowFailoverStrategy.apply — happy path
// ---------------------------------------------------------------------------

describe("TimeWindowFailoverStrategy — happy path", () => {
  it("outside the maintenance window: primary connector is first", () => {
    const result = applyAt(
      stripeRazorpayConfig(),
      [STRIPE, RAZORPAY],
      60 // 01:00 UTC
    );
    expect(result[0]).toBe(STRIPE);
  });

  it("inside the maintenance window: fallback connector is first", () => {
    const result = applyAt(
      stripeRazorpayConfig(),
      [STRIPE, RAZORPAY],
      130 // 02:10 UTC
    );
    expect(result[0]).toBe(RAZORPAY);
  });

  it("primary connector is still present in the list for retry", () => {
    const result = applyAt(
      stripeRazorpayConfig(),
      [STRIPE, RAZORPAY],
      130
    );
    expect(result).toContain(STRIPE);
  });

  it("returns correct RoutingDecision fields (in-window)", () => {
    const strategy = new TimeWindowFailoverStrategy(stripeRazorpayConfig());
    const { decisions } = strategy.apply([STRIPE, RAZORPAY], "pay_xyz", 130, "02:10 UTC");
    expect(decisions).toHaveLength(1);
    expect(decisions[0]).toMatchObject({
      strategy: "time_window_failover",
      primaryConnector: STRIPE,
      fallbackConnector: RAZORPAY,
      currentTimeUtc: "02:10 UTC",
      maintenanceWindowMatch: true,
      selectedConnector: RAZORPAY,
    });
  });

  it("returns correct RoutingDecision fields (out-of-window)", () => {
    const strategy = new TimeWindowFailoverStrategy(stripeRazorpayConfig());
    const { decisions } = strategy.apply([STRIPE, RAZORPAY], "pay_xyz", 60, "01:00 UTC");
    expect(decisions[0]).toMatchObject({
      maintenanceWindowMatch: false,
      selectedConnector: STRIPE,
    });
  });
});

