describe("TimeWindowFailoverStrategy — boundary tests", () => {
  it("at exactly the window start (inclusive): failover active", () => {
    const result = applyAt(stripeRazorpayConfig(), [STRIPE, RAZORPAY], 120); // 02:00
    expect(result[0]).toBe(RAZORPAY);
  });

  it("one minute before the window end: failover still active", () => {
    const result = applyAt(stripeRazorpayConfig(), [STRIPE, RAZORPAY], 149); // 02:29
    expect(result[0]).toBe(RAZORPAY);
  });

  it("at exactly the window end (exclusive): failover NOT active", () => {
    const result = applyAt(stripeRazorpayConfig(), [STRIPE, RAZORPAY], 150); // 02:30
    expect(result[0]).toBe(STRIPE);
  });

  it("one minute after the window end: no failover", () => {
    const result = applyAt(stripeRazorpayConfig(), [STRIPE, RAZORPAY], 151); // 02:31
    expect(result[0]).toBe(STRIPE);
  });
});

