describe("TimeWindowFailoverStrategy — failure modes", () => {
  it("malformed window_start_utc: window is skipped, list unchanged", () => {
    const config: MaintenanceWindowConfig = {
      windows: [
        {
          primaryConnector: STRIPE,
          fallbackConnector: RAZORPAY,
          windowStartUtc: "not-a-time",
          windowEndUtc: "02:30",
          enabled: true,
        },
      ],
    };
    const result = applyAt(config, [STRIPE, RAZORPAY], 130);
    expect(result[0]).toBe(STRIPE);
  });

  it("malformed window_end_utc: window is skipped, list unchanged", () => {
    const config: MaintenanceWindowConfig = {
      windows: [
        {
          primaryConnector: STRIPE,
          fallbackConnector: RAZORPAY,
          windowStartUtc: "02:00",
          windowEndUtc: "also-bad",
          enabled: true,
        },
      ],
    };
    const result = applyAt(config, [STRIPE, RAZORPAY], 130);
    expect(result[0]).toBe(STRIPE);
  });

  it("enabled = false: window is skipped even when time matches", () => {
    const config: MaintenanceWindowConfig = {
      windows: [
        {
          primaryConnector: STRIPE,
          fallbackConnector: RAZORPAY,
          windowStartUtc: "02:00",
          windowEndUtc: "02:30",
          enabled: false,
        },
      ],
    };
    const result = applyAt(config, [STRIPE, RAZORPAY], 130);
    expect(result[0]).toBe(STRIPE);
  });

  it("empty windows config: list unchanged", () => {
    const result = applyAt({ windows: [] }, [STRIPE, RAZORPAY], 130);
    expect(result).toEqual([STRIPE, RAZORPAY]);
  });

  it("fallback not in routing list: primary demoted to end", () => {
    // razorpay is absent from the list
    const result = applyAt(stripeRazorpayConfig(), [STRIPE, ADYEN], 130);
    expect(result[result.length - 1]).toBe(STRIPE); // primary at end
  });

  it("neither primary nor fallback in list: list unchanged", () => {
    const result = applyAt(stripeRazorpayConfig(), [ADYEN], 130);
    expect(result).toEqual([ADYEN]);
  });

  it("returns empty decisions array when config is empty", () => {
    const strategy = new TimeWindowFailoverStrategy({ windows: [] });
    const { decisions } = strategy.apply([STRIPE], "pay_1", 130);
    expect(decisions).toHaveLength(0);
  });
});

