describe("TimeWindowFailoverStrategy — midnight-crossing windows", () => {
  const midnightConfig: MaintenanceWindowConfig = {
    windows: [
      {
        primaryConnector: STRIPE,
        fallbackConnector: RAZORPAY,
        windowStartUtc: "23:00",
        windowEndUtc: "01:00",
        enabled: true,
      },
    ],
  };

  it("at 23:30: inside window (before midnight)", () => {
    const result = applyAt(midnightConfig, [STRIPE, RAZORPAY], 23 * 60 + 30);
    expect(result[0]).toBe(RAZORPAY);
  });

  it("at 00:30: inside window (after midnight)", () => {
    const result = applyAt(midnightConfig, [STRIPE, RAZORPAY], 30);
    expect(result[0]).toBe(RAZORPAY);
  });

  it("at 01:00: exclusive end — outside window", () => {
    const result = applyAt(midnightConfig, [STRIPE, RAZORPAY], 60);
    expect(result[0]).toBe(STRIPE);
  });

  it("at 12:00: well outside window", () => {
    const result = applyAt(midnightConfig, [STRIPE, RAZORPAY], 12 * 60);
    expect(result[0]).toBe(STRIPE);
  });
});

