/**
 * Integration tests for POST /v1/route and GET /health.
 *
 * Uses supertest to exercise the full Express app without starting a real port.
 * Time is controlled by setting nowMinutesUtc via the strategy directly;
 * the HTTP layer always passes `undefined` (current time), so we use
 * MAINTENANCE_WINDOWS_JSON env override to disable windows in default tests.
 */

import request from "supertest";
import { createApp } from "../../src/server";
import type { AppConfig } from "../../src/types";

// ---------------------------------------------------------------------------
// Fixtures
// ---------------------------------------------------------------------------

const outsideWindowConfig: AppConfig = {
  port: 3000,
  maintenanceWindows: { windows: [] }, // no windows → always primary first
};

const insideWindowConfig: AppConfig = {
  port: 3000,
  maintenanceWindows: {
    windows: [
      {
        primaryConnector: "stripe",
        fallbackConnector: "razorpay",
        windowStartUtc: "00:00", // entire day window for predictable test
        windowEndUtc: "23:59",
        enabled: true,
      },
    ],
  },
};

// ---------------------------------------------------------------------------
// GET /health
// ---------------------------------------------------------------------------

describe("GET /health", () => {
  const app = createApp(outsideWindowConfig);

  it("returns 200 with status ok", async () => {
    const res = await request(app).get("/health");
    expect(res.status).toBe(200);
    expect(res.body.status).toBe("ok");
    expect(res.body.service).toBe("routing-service");
    expect(typeof res.body.timestamp).toBe("string");
  });
});

// ---------------------------------------------------------------------------
// POST /v1/route — input validation
// ---------------------------------------------------------------------------

describe("POST /v1/route — input validation", () => {
  const app = createApp(outsideWindowConfig);

  it("returns 400 when paymentId is missing", async () => {
    const res = await request(app)
      .post("/v1/route")
      .send({ connectors: ["stripe"] });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/paymentId/i);
  });

  it("returns 400 when connectors is missing", async () => {
    const res = await request(app)
      .post("/v1/route")
      .send({ paymentId: "pay_1" });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/connectors/i);
  });

  it("returns 400 when connectors is an empty array", async () => {
    const res = await request(app)
      .post("/v1/route")
      .send({ paymentId: "pay_1", connectors: [] });
    expect(res.status).toBe(400);
  });

  it("returns 400 when connectors contains non-strings", async () => {
    const res = await request(app)
      .post("/v1/route")
      .send({ paymentId: "pay_1", connectors: [1, 2] });
    expect(res.status).toBe(400);
  });

  it("returns 400 when paymentId is an empty string", async () => {
    const res = await request(app)
      .post("/v1/route")
      .send({ paymentId: "   ", connectors: ["stripe"] });
    expect(res.status).toBe(400);
  });
});

// ---------------------------------------------------------------------------
// POST /v1/route — routing logic (no windows → passthrough)
// ---------------------------------------------------------------------------

describe("POST /v1/route — no maintenance windows", () => {
  const app = createApp(outsideWindowConfig);

  it("returns 200 with connectors in original order", async () => {
    const res = await request(app)
      .post("/v1/route")
      .send({ paymentId: "pay_123", connectors: ["stripe", "razorpay"] });

    expect(res.status).toBe(200);
    expect(res.body.paymentId).toBe("pay_123");
    expect(res.body.orderedConnectors).toEqual(["stripe", "razorpay"]);
    expect(res.body.decisions).toHaveLength(0);
    expect(typeof res.body.routedAt).toBe("string");
  });

  it("echoes back paymentId correctly", async () => {
    const res = await request(app)
      .post("/v1/route")
      .send({ paymentId: "pay_abc", connectors: ["adyen"] });
    expect(res.body.paymentId).toBe("pay_abc");
  });
});

// ---------------------------------------------------------------------------
// POST /v1/route — full-day window (always in maintenance)
// ---------------------------------------------------------------------------

describe("POST /v1/route — always-on maintenance window", () => {
  const app = createApp(insideWindowConfig);

  it("razorpay comes first when window covers current time", async () => {
    const res = await request(app).post("/v1/route").send({
      paymentId: "pay_999",
      connectors: ["stripe", "razorpay", "adyen"],
    });

    expect(res.status).toBe(200);
    expect(res.body.orderedConnectors[0]).toBe("razorpay");
    // stripe is preserved for retry
    expect(res.body.orderedConnectors).toContain("stripe");
  });

  it("decision records maintenanceWindowMatch = true", async () => {
    const res = await request(app).post("/v1/route").send({
      paymentId: "pay_888",
      connectors: ["stripe", "razorpay"],
    });

    expect(res.body.decisions).toHaveLength(1);
    expect(res.body.decisions[0].maintenanceWindowMatch).toBe(true);
    expect(res.body.decisions[0].selectedConnector).toBe("razorpay");
    expect(res.body.decisions[0].strategy).toBe("time_window_failover");
  });

  it("order is: razorpay → adyen → stripe", async () => {
    const res = await request(app).post("/v1/route").send({
      paymentId: "pay_777",
      connectors: ["stripe", "adyen", "razorpay"],
    });
    expect(res.body.orderedConnectors).toEqual(["razorpay", "adyen", "stripe"]);
  });
});

// ---------------------------------------------------------------------------
// 404
// ---------------------------------------------------------------------------

describe("unknown route", () => {
  const app = createApp(outsideWindowConfig);

  it("returns 404 for unknown paths", async () => {
    const res = await request(app).get("/unknown-path");
    expect(res.status).toBe(404);
  });
});

